async function seedDatabase() {
    try {
        if (process.env.NODE_ENV === 'production' && process.env.ALLOW_DESTRUCTIVE_SEED !== 'true') {
            throw new Error('Seed destruktif diblokir di production. Set ALLOW_DESTRUCTIVE_SEED=true jika benar-benar diperlukan.');
        }

        const mongoUri = process.env.MONGODB_URI || 'mongodb://localhost:27017/edubook';
        await mongoose.connect(mongoUri);
        console.log('✅ Terhubung ke MongoDB');

        await Book.deleteMany({});
        console.log('🗑️ Data buku lama dihapus');

        for (const page of bookData) {
            const manual = page.quiz_questions || [];
            const mcq = manual.filter(q => (q.question_type || 'mcq') === 'mcq');
            const existingFill = manual.filter(q => q.question_type === 'fill_blank');
            const existingArrange = manual.filter(q => q.question_type === 'arrange_words');

            const generated = generateForPage(page.page_number, page.paragraphs);
            const combinedMCQ = [...mcq, ...generated.mcq].slice(0, 200);
            const combinedFill = [...existingFill, ...generated.fill_blank].slice(0, 200);
            const combinedArrange = [...existingArrange, ...generated.arrange_words].slice(0, 200);

            page.quiz_questions = [...combinedMCQ, ...combinedFill, ...combinedArrange];
            console.log(`  Halaman ${page.page_number} (${page.title}): ${combinedMCQ.length} MCQ + ${combinedFill.length} Fill-Blank + ${combinedArrange.length} Arrange-Words = ${page.quiz_questions.length} soal`);
        }

        await Book.insertMany(bookData);
        console.log(`✅ ${bookData.length} halaman buku berhasil ditambahkan dengan Bank Soal Lengkap!`);

        const count = await Book.countDocuments();
        console.log(`📚 Total halaman di database saat ini: ${count}`);

        process.exit(0);
    } catch (error) {
        console.error('❌ Error database seeder:', error);
        process.exit(1);
    }
}

seedDatabase();
